-- Save MJ: Action Filters (core SP call only)
DECLARE @ID_59ef2169 UNIQUEIDENTIFIER,
@UserDescription_59ef2169 NVARCHAR(MAX),
@UserComments_59ef2169 NVARCHAR(MAX),
@Code_59ef2169 NVARCHAR(MAX),
@CodeExplanation_59ef2169 NVARCHAR(MAX)
SET
  @ID_59ef2169 = '9270AA31-975F-49C3-A16C-82CD009FED16'
SET
  @UserDescription_59ef2169 = N'Common: Status field changed in this save'
SET
  @UserComments_59ef2169 = N'Reusable transition detector for AfterUpdate bindings on any entity with a Status column (People, Organizations). MJ ships no seed ActionFilter rows (verified 2026-08-30) — the reusable piece upstream is the ActionFilterContext vocabulary this Code uses. Two behaviours to respect when attaching it: a CREATE reports no changes (DidFieldChange is false on insert), so never attach this to an AfterCreate-only binding; and filter evaluation is fail-closed — a prevented run still writes an ActionExecutionLog row.'
SET
  @Code_59ef2169 = N'return ActionFilterContext.DidFieldChange(''Status'');'
SET
  @CodeExplanation_59ef2169 = N'True only when the Status field''s value actually differs across this save — the binding fires on the transition, not on every update.' EXEC [${mjSchema}].spCreateActionFilter @ID = @ID_59ef2169,
  @UserDescription = @UserDescription_59ef2169,
  @UserComments = @UserComments_59ef2169,
  @Code = @Code_59ef2169,
  @CodeExplanation = @CodeExplanation_59ef2169;

GO

-- Save MJ: Action Filters (core SP call only)
DECLARE @ID_6b7a5138 UNIQUEIDENTIFIER,
@UserDescription_6b7a5138 NVARCHAR(MAX),
@UserComments_6b7a5138 NVARCHAR(MAX),
@Code_6b7a5138 NVARCHAR(MAX),
@CodeExplanation_6b7a5138 NVARCHAR(MAX)
SET
  @ID_6b7a5138 = 'EC35D675-FD23-4E99-81FF-87874BFE731C'
SET
  @UserDescription_6b7a5138 = N'Common: Status field changed to Ended in this save'
SET
  @UserComments_6b7a5138 = N'The ''field changed TO value'' shape — written as a transition, never as ''status IS Ended'', which would re-fire on every later save of an ended record. Loose compare per the ActionFilterContext contract. Same caveats as the plain status-changed filter: false on create, fail-closed evaluation.'
SET
  @Code_6b7a5138 = N'return ActionFilterContext.DidFieldChangeToValue(''Status'', ''Ended'');'
SET
  @CodeExplanation_6b7a5138 = N'True only on the save that moves Status to Ended, so a relationship''s end is logged exactly once per transition.' EXEC [${mjSchema}].spCreateActionFilter @ID = @ID_6b7a5138,
  @UserDescription = @UserDescription_6b7a5138,
  @UserComments = @UserComments_6b7a5138,
  @Code = @Code_6b7a5138,
  @CodeExplanation = @CodeExplanation_6b7a5138;

GO

